import pandas as pd
import numpy as np

ref_file = r"C:\Users\sandeeppawar\Downloads\aida-eval\data\file_generation_en\reference\FG_102\conflict_free_exam_questions_final_modified_res.xlsx"
pred_file = r"C:\Users\sandeeppawar\Downloads\aida-eval\runs\aida-ctrl\work\FG_102\conflict_free_exam_questions_final_modified.xlsx"

ref_df = pd.read_excel(ref_file, sheet_name=0)
pred_df = pd.read_excel(pred_file, sheet_name=0)

# Normalize for comparison
def normalize_value(val):
    if pd.isna(val):
        return None
    if isinstance(val, str):
        return val.strip()
    if isinstance(val, float):
        return round(val, 6)
    return val

def normalize_df(df):
    df_norm = df.copy()
    for col in df_norm.columns:
        df_norm[col] = df_norm[col].apply(normalize_value)
    return df_norm

ref_norm = normalize_df(ref_df)
pred_norm = normalize_df(pred_df)

# Sample comparison
total_rows = len(ref_df)
sample_size = min(30, total_rows // 10)

head_idx = list(range(min(sample_size, total_rows)))
tail_idx = list(range(max(0, total_rows - sample_size), total_rows))
middle_start = (total_rows // 2) - (sample_size // 2)
middle_idx = list(range(middle_start, min(middle_start + sample_size, total_rows)))

np.random.seed(42)
random_idx = np.random.choice(total_rows, size=min(sample_size, total_rows), replace=False).tolist()

all_samples = sorted(set(head_idx + tail_idx + middle_idx + random_idx))

print(f"Total rows: {total_rows}")
print(f"Sampling {len(all_samples)} rows for comparison")

mismatches = []
for idx in all_samples:
    for col in ref_df.columns:
        ref_val = ref_norm.iloc[idx][col]
        pred_val = pred_norm.iloc[idx][col]

        if ref_val != pred_val:
            if not (ref_val is None and pred_val is None):
                mismatches.append((idx, col, ref_val, pred_val))

print(f"\nMismatches in sample: {len(mismatches)}")
if mismatches:
    print("First 15 mismatches:")
    for m in mismatches[:15]:
        print(f"  Row {m[0]}, Col '{m[1]}': ref={m[2]}, pred={m[3]}")
else:
    print("No mismatches found in sample!")
